// Source device kernels and host planning retained; only named memory lifetime/ROI differs.
#define main historical_cli_main
#include "../quicksort-cuda/main.cu"
#undef main
#include <fstream>
#include <functional>
#include <memory>
#include <chrono>
constexpr uint SG=0xdeadbeef;
std::vector<uint64_t> loadwords(const char*name){std::ifstream io(name,std::ios::binary|std::ios::ate);size_t n=io.tellg();std::vector<uint64_t>v(n/8);io.seekg(0);io.read((char*)v.data(),n);return v;}
template<class T>uint64_t bits(T v){uint64_t out=0;memcpy(&out,&v,sizeof(T));return out;}
template<class T>T unbits(uint64_t v){T x;memcpy(&x,&v,sizeof(T));return x;}
template<class T>struct StudyCase{uint n,rounded,ng;T guard;std::vector<T>initial,dn,host;T*draw,*nraw;block_record<T>*br;parent_record*pr;work_record<T>*nr,*dr;std::vector<work_record<T>>work,done,news;std::vector<parent_record>parents;std::vector<block_record<T>>blocks;std::vector<uint>trace;};
template<class T>block_record<T> bg(T g){block_record<T>x;x.start=x.end=x.direction=x.parent=SG;x.pivot=g;return x;}
template<class T>work_record<T> wg(T g){work_record<T>x;x.start=x.end=x.direction=SG;x.pivot=g;return x;}
template<class T>void resetguards(StudyCase<T>&c){std::vector<T>v(c.rounded+2*c.ng,c.guard);gpucheck(cudaMemcpy(c.draw,v.data(),v.size()*sizeof(T),cudaMemcpyDefault));gpucheck(cudaMemcpy(c.nraw,v.data(),v.size()*sizeof(T),cudaMemcpyDefault));std::vector<block_record<T>>b(c.n+2,bg(c.guard));std::vector<parent_record>p(c.n+2,parent_record(SG,SG,SG,SG,SG));std::vector<work_record<T>>nw(2*c.n+2,wg(c.guard)),d(c.n+2,wg(c.guard));gpucheck(cudaMemcpy(c.br,b.data(),b.size()*sizeof(b[0]),cudaMemcpyDefault));gpucheck(cudaMemcpy(c.pr,p.data(),p.size()*sizeof(p[0]),cudaMemcpyDefault));gpucheck(cudaMemcpy(c.nr,nw.data(),nw.size()*sizeof(nw[0]),cudaMemcpyDefault));gpucheck(cudaMemcpy(c.dr,d.data(),d.size()*sizeof(d[0]),cudaMemcpyDefault));c.host=c.initial;gpucheck(cudaDeviceSynchronize());}
template<class T>void pipeline(StudyCase<T>&c){T*db=c.draw+c.ng,*dnb=c.nraw+c.ng;gpucheck(cudaMemcpy(db,c.host.data(),c.rounded*sizeof(T),cudaMemcpyHostToDevice));gpucheck(cudaMemcpy(dnb,c.dn.data(),c.rounded*sizeof(T),cudaMemcpyHostToDevice));const size_t MAXSEQ=optp(c.n,0.00009516,203);auto&work=c.work;auto&done=c.done;auto&news=c.news;auto&parents=c.parents;auto&blocks=c.blocks;work.clear();done.clear();news.clear();parents.clear();blocks.clear();c.trace.clear();uint pivot=median_host(c.host[0],c.host[c.n/2],c.host[c.n-1]);work.push_back(work_record<T>(0,c.n,pivot,1));while(!work.empty()){size_t blocksize=0;for(auto&w:work)blocksize+=std::max((w.end-w.start)/MAXSEQ,(size_t)1);for(auto&w:work){uint start=w.start,end=w.end,piv=w.pivot,direction=w.direction,count=(end-start+blocksize-1)/blocksize;parents.push_back(parent_record(start,end,start,end,count-1));for(uint i=0;i<count-1;i++)blocks.push_back(block_record<T>(start+blocksize*i,start+blocksize*(i+1),piv,direction,parents.size()-1));blocks.push_back(block_record<T>(start+blocksize*(count-1),end,piv,direction,parents.size()-1));}news.resize(2*blocks.size());gpucheck(cudaMemcpy(c.br+1,blocks.data(),blocks.size()*sizeof(block_record<T>),cudaMemcpyHostToDevice));gpucheck(cudaMemcpy(c.pr+1,parents.data(),parents.size()*sizeof(parent_record),cudaMemcpyHostToDevice));gpucheck(cudaMemcpy(c.nr+1,news.data(),news.size()*sizeof(work_record<T>),cudaMemcpyHostToDevice));gqsort_kernel<<<blocks.size(),GQSORT_LOCAL_WORKGROUP_SIZE>>>(db,dnb,c.br+1,c.pr+1,c.nr+1);gpucheck(cudaPeekAtLastError());gpucheck(cudaDeviceSynchronize());gpucheck(cudaMemcpy(news.data(),c.nr+1,news.size()*sizeof(work_record<T>),cudaMemcpyDeviceToHost));c.trace.push_back(blocks.size());work.clear();parents.clear();blocks.clear();for(auto&w:news)if(w.direction!=EMPTY_RECORD){if(w.end-w.start<=QUICKSORT_BLOCK_SIZE){if(w.end>w.start)done.push_back(w);}else work.push_back(w);}news.clear();}
if(!done.empty()){gpucheck(cudaMemcpy(c.dr+1,done.data(),done.size()*sizeof(work_record<T>),cudaMemcpyHostToDevice));lqsort_kernel<<<done.size(),LQSORT_LOCAL_WORKGROUP_SIZE>>>(db,dnb,c.dr+1);gpucheck(cudaPeekAtLastError());gpucheck(cudaDeviceSynchronize());}gpucheck(cudaMemcpy(c.host.data(),db,c.rounded*sizeof(T),cudaMemcpyDeviceToHost));}
template<class T>void append(std::vector<uint64_t>&v,const std::vector<T>&x){for(T z:x)v.push_back(bits(z));}
template<class T>bool capture(StudyCase<T>&c,std::vector<uint64_t>&out){bool ok=std::equal(c.dn.begin(),c.dn.end(),c.host.begin());append(out,c.host);append(out,c.dn);std::vector<T>v(c.rounded+2*c.ng);for(int pb=0;pb<2;pb++){T*p=pb?c.nraw:c.draw;gpucheck(cudaMemcpy(v.data(),p,v.size()*sizeof(T),cudaMemcpyDeviceToHost));for(uint i=0;i<c.ng;i++){ok&=v[i]==c.guard;out.push_back(bits(v[i]));}for(uint i=c.ng+c.rounded;i<v.size();i++){ok&=v[i]==c.guard;out.push_back(bits(v[i]));}if(p==c.nraw)for(uint i=c.ng+c.n;i<c.ng+c.rounded;i++){ok&=v[i]==c.guard;out.push_back(bits(v[i]));}}
for(int gi=0;gi<2;gi++){uint i=gi?c.n+1:0;block_record<T>x;gpucheck(cudaMemcpy(&x,c.br+i,sizeof(x),cudaMemcpyDeviceToHost));ok&=x.start==SG&&x.end==SG&&x.direction==SG&&x.parent==SG&&x.pivot==c.guard;out.insert(out.end(),{x.start,x.end,bits(x.pivot),x.direction,x.parent});}for(int gi=0;gi<2;gi++){uint i=gi?c.n+1:0;parent_record x(0,0,0,0,0);gpucheck(cudaMemcpy(&x,c.pr+i,sizeof(x),cudaMemcpyDeviceToHost));ok&=x.sstart==SG&&x.send==SG&&x.oldstart==SG&&x.oldend==SG&&x.blockcount==SG;out.insert(out.end(),{x.sstart,x.send,x.oldstart,x.oldend,x.blockcount});}for(int which=0;which<2;which++){auto*p=which?c.dr:c.nr;uint end=which?c.n+1:2*c.n+1;for(int gi=0;gi<2;gi++){uint i=gi?end:0;work_record<T>x;gpucheck(cudaMemcpy(&x,p+i,sizeof(x),cudaMemcpyDeviceToHost));ok&=x.start==SG&&x.end==SG&&x.direction==SG&&x.pivot==c.guard;out.insert(out.end(),{x.start,x.end,bits(x.pivot),x.direction});}}return ok;}
template<class T>std::shared_ptr<StudyCase<T>>makecase(uint n,uint rounded,const std::vector<uint64_t>&f,size_t&pos){auto c=std::make_shared<StudyCase<T>>();c->n=n;c->rounded=rounded;c->ng=256/sizeof(T);c->guard=std::is_same<T,uint>::value?T(UINT_MAX):T(-1234567);for(uint i=0;i<rounded;i++)c->initial.push_back(unbits<T>(f[pos++]));for(uint i=0;i<rounded;i++)c->dn.push_back(unbits<T>(f[pos++]));gpucheck(cudaMalloc(&c->draw,(rounded+2*c->ng)*sizeof(T)));gpucheck(cudaMalloc(&c->nraw,(rounded+2*c->ng)*sizeof(T)));gpucheck(cudaMalloc(&c->br,(n+2)*sizeof(block_record<T>)));gpucheck(cudaMalloc(&c->pr,(n+2)*sizeof(parent_record)));gpucheck(cudaMalloc(&c->nr,(2*n+2)*sizeof(work_record<T>)));gpucheck(cudaMalloc(&c->dr,(n+2)*sizeof(work_record<T>)));c->work.reserve(n);c->done.reserve(n);c->news.reserve(2*n);c->parents.reserve(n);c->blocks.reserve(n);c->trace.reserve(n);c->host=c->initial;resetguards(*c);pipeline(*c);cudaFuncAttributes ga,la;gpucheck(cudaFuncGetAttributes(&ga,gqsort_kernel<T>));gpucheck(cudaFuncGetAttributes(&la,lqsort_kernel<T>));printf("STUDY_SOURCE_RESOURCE sizeofT=%zu record_block=%zu record_work=%zu gq_shared=%zu lq_shared=%zu\n",sizeof(T),sizeof(block_record<T>),sizeof(work_record<T>),ga.sharedSizeBytes,la.sharedSizeBytes);return c;}
int main(){auto f=loadwords(QS_FIXTURE);size_t pos=1;std::vector<std::function<double(std::vector<uint64_t>&,bool&,std::vector<uint>&)>>runs;for(uint ci=0;ci<f[0];ci++){uint type=f[pos++],n=f[pos++],mode=f[pos++],rounded=f[pos++];auto add=[&](auto c){runs.push_back([c](std::vector<uint64_t>&out,bool&ok,std::vector<uint>&counts){resetguards(*c);auto start=std::chrono::steady_clock::now();pipeline(*c);double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();ok&=capture(*c,out);counts.push_back(c->trace.size());counts.push_back(c->done.size());for(uint x:c->trace)counts.push_back(x);return t;});};if(type==0)add(makecase<uint>(n,rounded,f,pos));else if(type==1)add(makecase<float>(n,rounded,f,pos));else add(makecase<double>(n,rounded,f,pos));}for(int trial=1;trial<=5;trial++){auto payload=f;bool ok=true;double total=0;std::vector<double>times;std::vector<uint>counts;for(auto&run:runs){double t=run(payload,ok,counts);total+=t;times.push_back(t);}std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream io(path,std::ios::binary);io.write((char*)payload.data(),payload.size()*8);io.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"timing_region\":\"sum24_preallocated_source_custom_quicksort_H2D_hostqueue_kernels_D2H\",\"jit_excluded\":true,\"internal_repeats\":1,\"case_times_seconds\":[",trial,total,ok?"true":"false",payload.size(),ok?0:1);for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("],\"stage_count_encoding\":\"percase:gq_rounds,local_sequences,gq_blocks_eachround\",\"stage_counts\":[");for(size_t i=0;i<counts.size();i++)printf("%s%u",i?",":"",counts[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 3;}return 0;}
